{"plan_objective_id": 1, "updated_plan_objective_json": "{
  "id": 1,
  "objective": "Search for published data on run-to-run repeatability of gas atomization processes",
  "rationale": "Core question",
  "status": "completed",
  "result": "Found NIST Slotwinski 2014 (4 containers 17-4SS, 15 containers CoCr from same lot), Grubbs 2022 (19 lots Al5056 and Ta), Anderson 2002 (gas flow reproducibility), Pennacchio 2026 (4 atmosphere configs 316L), Smith/Sudbrack 2017 NASA (19 IN718 lots). Zhang 2025 (yield data). Cordova 2023 (Ti6Al4V 6 builds).",
  "evaluation": "Multiple datasets with quantitative variability measures obtained."
}"}

{"plan_objective_id": 2, "updated_plan_objective_json": "{
  "id": 2,
  "objective": "Search for lot-to-lot variability data for AM-specific powders",
  "rationale": "Industrial AM powder variability is key",
  "status": "completed",
  "result": "Found Cordova 2023 (Ti6Al4V ELI, virgin vs reused, 6 builds), Brika 2020 (3 lots Ti-6Al-4V), Gibbons 2026 (175 reuse cycles Ti-6Al-4V ELI), Smith/Sudbrack NASA 2017 (19 IN718 lots), Ellis/Sudbrack 2019 (18 powders IN718). Reijonen 2021 (316L cross-testing). Grubbs 2022 (Al5056, Ta).",
  "evaluation": "Good coverage across alloys."
}"}

{"plan_objective_id": 3, "updated_plan_objective_json": "{
  "id": 3,
  "objective": "Search for NIST, NASA, ASTM interlaboratory studies on powder variability and qualification",
  "rationale": "Standardization studies",
  "status": "completed",
  "result": "NIST: Slotwinski 2014 (15 CoCr vials for round robin), Cooke 2012. NASA: Smith/Sudbrack 2017 (19 lots IN718), McElderry 2022 MSFC, Glendening 2020 MSFC-STD-3716. ASTM: Standardization Roadmap 2017 referencing F3049 and B215.",
  "evaluation": "Good coverage."
}"}

{"plan_objective_id": 4, "updated_plan_objective_json": "{
  "id": 4,
  "objective": "Search for guidance on number of replicate runs needed to establish process baselines",
  "rationale": "User specifically asks about this",
  "status": "completed",
  "result": "No published standard specifies a minimum number of atomization heats or lots. ASTM F3049 references sampling but not lot count. NASA MSFC-STD-3716 uses SPC framework without specifying minimum heats. Anderson 2002 showed 2 replicate mass-flow measurements giving ~4-10% scatter. Marinucci 2023 used 4 initial runs for process development. The absence of explicit guidance is itself a finding.",
  "evaluation": "Confirmed gap in literature - this is a key finding to report."
}"}

{"plan_objective_id": 5, "updated_plan_objective_json": "{
  "id": 5,
  "objective": "Gather detailed evidence from all retrieved papers and extract quantitative data",
  "rationale": "Need specific numbers",
  "status": "completed",
  "result": "Extracted detailed quantitative data from key papers.",
  "evaluation": "Sufficient data collected."
}"}

{"plan_objective_id": 6, "updated_plan_objective_json": "{
